   427→#[test]
   428→fun test_new_emode_group() {
   429→    use sui::test_scenario;
   430→
   431→    let mut scenario = test_scenario::begin(@0x1);
   432→    let ctx = scenario.ctx();
   433→
   434→    let mut registry = new_e_mode_registry(ctx);
   435→
   436→    // init condition is correct
   437→    assert!(registry.next_group_id == 0, 0);
   438→    assert!(!registry.groups.contains(0), 1);
   439→
   440→    // Create a new emode group
   441→    let group1 = registry.new_emode_group(0, scenario.ctx());
   442→    assert!(group1 == 0, 2);
   443→    assert!(registry.next_group_id == 1, 3);
   444→    assert!(registry.groups.contains(0), 4);
   445→
   446→    // Create another emode group
   447→    let group2 = registry.new_emode_group(0, scenario.ctx());
   448→    assert!(group2 == 1, 5);
   449→    assert!(registry.next_group_id == 2, 6);
   450→    assert!(registry.groups.contains(1), 7);
   451→
   452→    scenario.end();
   453→    std::unit_test::destroy(registry);
   454→}
